import { EdkValidationError } from "../../../elementum-entity-client/errors.js";
import { slimTokens, } from "../../catalog/index.js";
export const visualFlowPosition = {
    top: "TOP",
    right: "RIGHT",
    bottom: "BOTTOM",
    left: "LEFT",
};
export const visualFlowSymbol = {
    square: "SQUARE",
    diamond: "DIAMOND",
    circle: "CIRCLE",
};
export function flowAgentAction(agent, name) {
    return { kind: "agent", agent, ...(name !== undefined ? { name } : {}) };
}
export function flowAutomationAction(automation, name) {
    return { kind: "automation", automation, ...(name !== undefined ? { name } : {}) };
}
export function flowUserAction(name) {
    return { kind: "user", name };
}
export function flowApiAction(name) {
    return { kind: "api", name };
}
export function flowObjectAction(object, name) {
    return { kind: "object", object, ...(name !== undefined ? { name } : {}) };
}
export function flowObjectTarget(object, name) {
    return { object, ...(name !== undefined ? { name } : {}) };
}
/** Define the immutable visual process diagram attached to an app. */
export function visualFlow(opts) {
    const owner = opts.app;
    if (owner?.__kind !== "app") {
        throw new EdkValidationError("visualFlow requires an app owner because elements do not expose stages.");
    }
    if (Object.keys(opts.stages).length === 0)
        throw new EdkValidationError("visualFlow requires at least one stage.");
    for (const [stageKey, stage] of Object.entries(opts.stages)) {
        if (stageKey.trim() === "")
            throw new EdkValidationError("visualFlow stage keys must be non-empty.");
        const keys = new Set(Object.keys(stage.nodes));
        for (const [key, node] of Object.entries(stage.nodes)) {
            if (!Number.isFinite(node.x) || !Number.isFinite(node.y)) {
                throw new EdkValidationError(`visualFlow node ${JSON.stringify(key)}: x and y must be finite numbers.`);
            }
            if (node.action?.kind === "agent" && node.action.agent.parent !== owner.refName) {
                throw new EdkValidationError(`visualFlow node ${JSON.stringify(key)}: agent must belong to ${owner.__kind} ${JSON.stringify(owner.refName)}.`);
            }
            if (node.action?.kind === "automation" && node.action.automation.parent !== owner.refName) {
                throw new EdkValidationError(`visualFlow node ${JSON.stringify(key)}: automation must belong to ${owner.__kind} ${JSON.stringify(owner.refName)}.`);
            }
            for (const connection of node.connectsTo ?? []) {
                const target = typeof connection === "string" ? connection : connection.target;
                if (!keys.has(target))
                    throw new EdkValidationError(`visualFlow node ${JSON.stringify(key)} connects to unknown node ${JSON.stringify(target)} in stage ${JSON.stringify(stageKey)}.`);
            }
        }
    }
    return {
        def(refName) {
            return {
                kind: "visual-flow",
                parent: owner.refName,
                refName,
                payload: slimTokens({ stages: Object.entries(opts.stages).map(([stage, value]) => ({ stage, nodes: value.nodes })) }),
                ...(opts.enabled !== undefined ? { enabled: opts.enabled } : {}),
            };
        },
    };
}
